import"./chunk-ZW5NV4UO.js";var e={en:{title:"Romance books on Mastodon: readers, authors and hashtags",description:"Find romance readers, authors and book conversations on Mastodon. Choose people and hashtags across romance genres, then preview your feed.",heading:"Romance books on Mastodon",listTitle:"Romance books",intro:["Find your next love story and people to talk about it with. Explore romance novels, reader recommendations, reviews and authors sharing their work, from contemporary and historical romance to romantasy and queer love stories.","Choose people and hashtags, then preview their posts before following. Relevant tags remain available even when quiet: small reading communities need somewhere to start. Book content and author updates matter more than a genre word in a profile."],faq:[{q:"Do I need an account?",a:"Browse and preview public posts without an account. Sign in with your Mastodon account to follow your selection or create a list."},{q:"Which kinds of romance belong here?",a:"Romance across subgenres belongs here, including contemporary, historical, paranormal, romantic suspense, romantasy, New Adult and LGBTQ+ romance. Reading, reviewing, translating and writing romance all count. Hashtags are open conversations and may include mature themes, so preview the posts and choose what suits you."},{q:"How do I get onto this list?",a:"Share romance book content regularly and allow your server to suggest your profile. Substantive author updates count too; a bio keyword alone does not. For help or removal, contact @mawkingbird@mastodon.social."}]},de:{title:"Liebesromane auf Mastodon: Menschen und Hashtags entdecken",description:"Entdecke Menschen, die Liebesromane lesen und schreiben. W\xE4hle Profile und Hashtags von Romance bis Romantasy und sieh dir deinen Feed vorab an.",heading:"Liebesromane auf Mastodon",listTitle:"Liebesromane",intro:["Entdecke deine n\xE4chste Liebesgeschichte und Menschen, mit denen du dar\xFCber sprechen kannst. Hier findest du Lesetipps, Rezensionen und Einblicke ins Schreiben: von zeitgen\xF6ssischen und historischen Liebesromanen bis zu Romantasy und queeren Liebesgeschichten.","W\xE4hle Profile und Hashtags aus und schau dir die Beitr\xE4ge in der Vorschau an. Auch passende Hashtags mit wenigen oder noch gar keinen Beitr\xE4gen bleiben dabei: Kleine Lesegemeinschaften brauchen einen Anfang. Entscheidend sind Beitr\xE4ge \xFCber B\xFCcher, nicht blo\xDF ein Genre im Profiltext."],faq:[{q:"Brauche ich ein Konto?",a:"Du kannst die Auswahl und \xF6ffentliche Beitr\xE4ge ohne Konto ansehen. Melde dich mit deinem Mastodon-Konto an, um Profilen und Hashtags zu folgen oder eine Liste anzulegen."},{q:"Welche Liebesromane geh\xF6ren dazu?",a:"Alle Spielarten sind willkommen: zeitgen\xF6ssische und historische Liebesromane, Paranormal Romance, Romantic Suspense, Romantasy, New Adult und LGBTQ+-Romance. Lesen, Rezensieren, \xDCbersetzen und Schreiben geh\xF6ren gleicherma\xDFen dazu. Hashtags sind offene Gespr\xE4che und k\xF6nnen auch Inhalte f\xFCr Erwachsene enthalten. Schau deshalb in die Vorschau und w\xE4hle, was zu dir passt."},{q:"Wie komme ich auf diese Liste?",a:"Teile regelm\xE4\xDFig Beitr\xE4ge \xFCber Liebesromane und erlaube deinem Server, dein Profil vorzuschlagen. Inhaltliche Einblicke in eigene B\xFCcher z\xE4hlen ebenfalls; ein Schlagwort im Profil allein reicht nicht. F\xFCr Hilfe oder eine Entfernung kontaktiere @mawkingbird@mastodon.social."}]}};export{e as COPY};
